import io,unittest
from recordtools import export_rows
class ExportTests(unittest.TestCase):
    def test_column_order(self):
        result=io.StringIO();export_rows([{"note":"plain","id":"7"}],result)
        self.assertEqual(result.getvalue(),"id,note\r\n7,plain\r\n")
    def test_empty(self):
        result=io.StringIO();export_rows([],result)
        self.assertEqual(result.getvalue(),"id,note\r\n")
